-- ----- practice-test-results.sql -----
-- Practice test results — run in Supabase SQL editor
create table if not exists public.practice_test_results (
  result_id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.users(user_id) on delete cascade,
  course_id uuid not null references public.courses(course_id) on delete cascade,
  test_type text not null check (test_type in ('practice_quiz', 'simulated_exam')),
  topic_filter text,            -- topic name if user filtered to one topic
  question_count integer not null,
  correct_count integer not null default 0,
  score_pct numeric(5,2),       -- 0–100
  missed_topics jsonb default '[]'::jsonb,   -- [{topic, wrong_count}]
  mastery_updates jsonb default '[]'::jsonb, -- [{topic_id, topic_name, old_score, new_score}]
  duration_seconds integer,     -- simulated exam only
  created_at timestamptz not null default now()
);

alter table public.practice_test_results enable row level security;

drop policy if exists "Users manage own practice results" on public.practice_test_results;
create policy "Users manage own practice results"
  on public.practice_test_results
  for all
  using (auth.uid() = user_id)
  with check (auth.uid() = user_id);


-- ----- course-web-suggestions.sql -----
-- Stores web-searched syllabus/course content surfaced to the user for approval.
-- Fires automatically on course creation when no syllabus is uploaded.

create table if not exists public.course_web_suggestions (
  id           uuid        primary key default gen_random_uuid(),
  course_id    uuid        not null references public.courses(course_id) on delete cascade,
  user_id      uuid        not null references auth.users(id) on delete cascade,
  title        text,
  url          text,
  content      text        not null,
  status       text        not null default 'pending'
               check (status in ('pending', 'approved', 'dismissed')),
  created_at   timestamptz not null default now()
);

alter table public.course_web_suggestions enable row level security;

drop policy if exists "Users manage their own web suggestions" on public.course_web_suggestions;
create policy "Users manage their own web suggestions"
  on public.course_web_suggestions
  for all
  using  (auth.uid() = user_id)
  with check (auth.uid() = user_id);


-- ----- user-keys.sql -----
-- Generic per-user key store (metadata only).
-- Secret values are stored encrypted in Supabase Vault (see vault-helpers.sql);
-- key_value is nullable because plaintext secrets are migrated out via
-- user-keys-vault-migration.sql. New writes never store plaintext here.
CREATE TABLE IF NOT EXISTS user_keys (
  user_id  UUID REFERENCES auth.users(id) ON DELETE CASCADE,
  key_name TEXT NOT NULL,
  key_value TEXT,
  updated_at TIMESTAMPTZ DEFAULT now(),
  PRIMARY KEY (user_id, key_name)
);

-- Idempotent: relax legacy NOT NULL on existing deployments so plaintext can be removed.
ALTER TABLE user_keys ALTER COLUMN key_value DROP NOT NULL;

ALTER TABLE user_keys ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users manage their own keys" ON user_keys;
CREATE POLICY "Users manage their own keys"
  ON user_keys FOR ALL
  USING (auth.uid() = user_id)
  WITH CHECK (auth.uid() = user_id);


