-- ----- fsrs-review-rpc.sql -----
-- Atomic FSRS + topic mastery update. Replaces the two-step write in
-- /api/cards/review/route.ts so a partial failure can't leave the card
-- marked reviewed without bumping mastery (or vice versa).
--
-- SECURITY DEFINER is required so the function can update topic_mastery
-- across users while still letting a logged-in caller invoke it. The
-- explicit user_id check in the WHERE clause is what enforces the
-- per-user boundary; do not remove it.

-- Drop the old (buggy) signature if it exists. The first revision of this file
-- declared p_fsrs_state as integer, but flashcards.fsrs_state is a text column
-- with a CHECK ('new','learning','review','relearning'), and the route passes
-- a string. The integer signature made every call fail 500.
drop function if exists public.review_card_atomic(
  uuid, uuid, numeric, numeric, integer, integer, integer, timestamptz, date, numeric
);

create or replace function public.review_card_atomic(
  p_card_id uuid,
  p_user_id uuid,
  p_fsrs_stability numeric,
  p_fsrs_difficulty numeric,
  p_fsrs_reps integer,
  p_fsrs_lapses integer,
  p_fsrs_state text,
  p_fsrs_last_review timestamptz,
  p_fsrs_next_review_date date,
  p_mastery_delta numeric
) returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_topic_id uuid;
begin
  update public.flashcards
  set fsrs_stability = p_fsrs_stability,
      fsrs_difficulty = p_fsrs_difficulty,
      fsrs_reps = p_fsrs_reps,
      fsrs_lapses = p_fsrs_lapses,
      fsrs_state = p_fsrs_state,
      fsrs_last_review = p_fsrs_last_review,
      fsrs_next_review_date = p_fsrs_next_review_date
  where card_id = p_card_id
    and user_id = p_user_id
  returning topic_id into v_topic_id;

  if not found then
    raise exception 'card not found or not owned by user';
  end if;

  if v_topic_id is not null then
    insert into public.topic_mastery (user_id, topic_id, mastery_score, confidence, last_updated)
    values (p_user_id, v_topic_id, greatest(0, least(1, p_mastery_delta)), 0, now())
    on conflict (user_id, topic_id) do update
      set mastery_score = greatest(0, least(1, coalesce(public.topic_mastery.mastery_score, 0) + p_mastery_delta)),
          last_updated = now();

    insert into public.mastery_history (user_id, topic_id, mastery_score)
    select user_id, topic_id, mastery_score
    from public.topic_mastery
    where user_id = p_user_id
      and topic_id = v_topic_id;
  end if;
end;
$$;

grant execute on function public.review_card_atomic(
  uuid, uuid, numeric, numeric, integer, integer, text, timestamptz, date, numeric
) to authenticated, service_role;


-- ----- rag-functions.sql -----
-- RAG vector similarity search function
-- Run in Supabase SQL Editor before using Phase 17 RAG features.

create or replace function match_material_chunks(
  p_user_id    uuid,
  p_course_id  uuid,
  p_query_embedding vector(1536),
  p_top_k      integer default 5
)
returns table (
  material_id  uuid,
  chunk_index  integer,
  content      text
)
language sql
stable
as $$
  select
    me.material_id,
    me.chunk_index,
    me.content
  from material_embeddings me
  join materials m on m.material_id = me.material_id
  where me.user_id = p_user_id
    and m.course_id = p_course_id
    and me.embedding is not null
  order by me.embedding <=> p_query_embedding
  limit p_top_k;
$$;

grant execute on function match_material_chunks(uuid, uuid, vector, integer) to service_role;


-- ----- vault-delete.sql -----
-- Run this in the Supabase SQL editor after vault-helpers.sql.
-- Adds delete wrappers so service-role API routes can permanently remove user-scoped
-- secrets (key removal on DELETE, account deletion, calendar disconnect) instead of
-- blanking them to an empty string. Safe to run more than once.

create or replace function delete_user_secret(p_user_id uuid, p_secret_name text)
returns void
language plpgsql
security definer
set search_path = public, vault
as $$
declare
  secret_name text := 'user_secret_' || p_user_id::text || '_' || p_secret_name;
begin
  if p_secret_name !~ '^[a-z0-9_]+$' then
    raise exception 'Invalid secret name';
  end if;

  delete from vault.secrets where name = secret_name;
end;
$$;

create or replace function delete_user_api_key(p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = public, vault
as $$
declare
  secret_name text := 'api_key_' || p_user_id::text;
begin
  delete from vault.secrets where name = secret_name;
end;
$$;

grant execute on function delete_user_secret(uuid, text) to service_role;
grant execute on function delete_user_api_key(uuid) to service_role;


-- ----- rag-keyword-index.sql -----
-- RAG keyword fallback full-text index.
-- Run in the Supabase SQL editor after schema.sql (and rag-functions.sql).
--
-- The keyword fallback in lib/rag.ts runs a plain text search against
-- public.material_embeddings.content, which Postgres executes as
--   content @@ plainto_tsquery('english', ...).
-- Without an index this is a sequential scan that recomputes to_tsvector per
-- row. This GIN index on to_tsvector('english', content) lets the planner use
-- the index, making the keyword fallback scalable for larger material sets.
--
-- Idempotent: CREATE INDEX IF NOT EXISTS is a no-op on re-run. The tsvector
-- config ('english') must match the config pinned in lib/rag.ts so the
-- expression index is usable by the query.

create index if not exists material_embeddings_content_fts
  on public.material_embeddings
  using gin (to_tsvector('english', content));


-- ======================================================================
-- SECTION 7. One-time data backfills and migrations
-- ======================================================================

-- ----- content-coverage-backfill.sql -----
-- Backfill topics.content_coverage based on existing flashcard counts.
-- Coverage = min(1.0, card_count / 10). Run once after deploying the flashcard
-- agent change that writes coverage on insert. Safe to re-run: deterministic.

update public.topics t
set content_coverage = least(
  1.0,
  (
    select count(*)::numeric / 10
    from public.flashcards f
    where f.topic_id = t.topic_id
  )
);


-- ----- user-keys-vault-migration.sql -----
-- One-time migration: move any plaintext per-user secrets still held in
-- public.user_keys (e.g. OpenAI keys set before Vault storage was added) into the
-- Vault, then remove the plaintext rows. Idempotent: once rows are migrated and
-- deleted, re-running is a no-op. Requires vault-helpers.sql to be applied first.

do $$
declare
  r record;
begin
  for r in
    select user_id, key_name, key_value
    from public.user_keys
    where key_value is not null
      and key_value <> ''
      and key_name ~ '^[a-z0-9_]+$'
  loop
    -- Store under the same name the app reads via get_user_secret().
    perform public.store_user_secret(r.user_id, r.key_name, r.key_value);
    -- Drop the plaintext copy now that the Vault holds it.
    delete from public.user_keys
    where user_id = r.user_id and key_name = r.key_name;
  end loop;
end $$;


-- ======================================================================
-- SECTION 8. Hosted multi-tenant security hardening
-- ======================================================================

-- ----- security-hardening.sql -----
-- ============================================================
-- HOSTED MULTI-TENANT SECURITY HARDENING (Phase 0)
-- Run after the rest of the schema. Idempotent / safe to re-run.
-- Required before opening public sign-up.
-- ============================================================

-- ── 1. Lock down exposed SECURITY DEFINER RPCs ───────────────
-- These functions are SECURITY DEFINER and take a caller-supplied user_id with
-- NO internal auth.uid() check, and they are reachable via the public Data API
-- (PostgREST) by anyone holding the public anon key. Postgres grants EXECUTE to
-- PUBLIC by default, so without these REVOKEs any visitor can decrypt every
-- user's API keys (get_user_*) or rewrite another user's flashcard state
-- (review_card_atomic). The app only ever calls them with the service-role
-- client, which retains EXECUTE, so revoking from anon/authenticated/public is
-- safe and closes the hole.

revoke execute on function public.get_user_api_key(uuid)                         from anon, authenticated, public;
revoke execute on function public.get_user_secret(uuid, text)                    from anon, authenticated, public;
revoke execute on function public.store_user_api_key(uuid, text)                 from anon, authenticated, public;
revoke execute on function public.store_user_secret(uuid, text, text)            from anon, authenticated, public;
revoke execute on function public.delete_user_api_key(uuid)                      from anon, authenticated, public;
revoke execute on function public.delete_user_secret(uuid, text)                 from anon, authenticated, public;
revoke execute on function public.review_card_atomic(uuid, uuid, numeric, numeric, integer, integer, text, timestamptz, date, numeric)
                                                                                 from anon, authenticated, public;

-- Re-assert that only the service role (used by all server routes) can call them.
grant execute on function public.get_user_api_key(uuid)                          to service_role;
grant execute on function public.get_user_secret(uuid, text)                     to service_role;
grant execute on function public.store_user_api_key(uuid, text)                  to service_role;
grant execute on function public.store_user_secret(uuid, text, text)             to service_role;
grant execute on function public.delete_user_api_key(uuid)                       to service_role;
grant execute on function public.delete_user_secret(uuid, text)                  to service_role;
grant execute on function public.review_card_atomic(uuid, uuid, numeric, numeric, integer, integer, text, timestamptz, date, numeric)
                                                                                 to service_role;

-- ── 2. Explicit WITH CHECK on all 18 user-scoped policies ────
-- PostgreSQL already falls back to the USING expression as the implicit
-- WITH CHECK, so this is defense-in-depth: it makes the INSERT/UPDATE row
-- constraint explicit instead of relying on the engine default. ALTER POLICY
-- preserves the existing USING clause and is idempotent.

alter policy "users: own row only" on public.users with check (auth.uid() = user_id);
alter policy "professors: own rows only" on public.professors with check (auth.uid() = user_id);
alter policy "courses: own rows only" on public.courses with check (auth.uid() = user_id);
alter policy "topics: own rows only" on public.topics with check (auth.uid() = user_id);
alter policy "topic_mastery: own rows only" on public.topic_mastery with check (auth.uid() = user_id);
alter policy "flashcards: own rows only" on public.flashcards with check (auth.uid() = user_id);
alter policy "exams: own rows only" on public.exams with check (auth.uid() = user_id);
alter policy "assignments: own rows only" on public.assignments with check (auth.uid() = user_id);
alter policy "materials: own rows only" on public.materials with check (auth.uid() = user_id);
alter policy "inbox_items: own rows only" on public.inbox_items with check (auth.uid() = user_id);
alter policy "session_log: own rows only" on public.session_log with check (auth.uid() = user_id);
alter policy "session_messages: own rows only" on public.session_messages with check (auth.uid() = user_id);
alter policy "nudges: own rows only" on public.nudges with check (auth.uid() = user_id);
alter policy "wiki_versions: own rows only" on public.wiki_versions with check (auth.uid() = user_id);
alter policy "study_plan: own rows only" on public.study_plan with check (auth.uid() = user_id);
alter policy "mastery_history: own rows only" on public.mastery_history with check (auth.uid() = user_id);
alter policy "material_embeddings: own rows only" on public.material_embeddings with check (auth.uid() = user_id);
alter policy "calendar_connections: own rows only" on public.calendar_connections with check (auth.uid() = user_id);

-- ── 3. Unique constraints behind the de-dup logic ───────────
-- onboarding/complete dedupes professors/courses by name (select-then-insert =
-- TOCTOU), and courses/create inserts a professor unconditionally (duplicates
-- on every course-create). These unique indexes make the dedup race-safe and
-- let the routes use upsert-on-conflict.
-- NOTE: if applied to a DB that already has duplicate (user_id,name) rows, the
-- index creation will fail — de-dupe first. On a fresh hosted DB there is no
-- existing data, so it creates cleanly.
create unique index if not exists professors_user_name_uniq on public.professors (user_id, name);
create unique index if not exists courses_user_name_uniq    on public.courses (user_id, name);
